    make(3, "將白花莖插入紅色水中，數小時後花瓣出現紅色細線，最直接支持哪項結論？", {"A": "水可沿著莖內某些運輸構造到達花瓣", "B": "紅色染料一定經由韌皮部把糖類送到花瓣", "C": "花瓣自行製造紅色染料並輸入莖", "D": "所有植物的養分與水都只走同一條管道"}, "染色水在花瓣出現表示水或染料沿莖內的運輸構造移動；實驗可支持路徑存在，但不能只憑顏色判定所有物質或完整機制。", "實驗題先分開直接看到的顏色與需要額外證據的組織、機制推論。", ["寫出實驗真正觀察到的是花瓣出現紅色細線。", "將觀察連到水或染料沿莖移動。", "推論可能涉及木質部等輸水構造。", "標記不能由單一顏色直接證明韌皮部與所有植物。", "所以選 A。"], "medium"),
    make(4, "蒸散作用對植物內水分運輸的主要影響為何？", {"A": "葉片水分散失造成連續水柱張力，有助於拉動根部吸收的水向上移動", "B": "蒸散會把葉片製造的糖全部轉成水", "C": "蒸散只發生在根毛，與葉片氣孔無關", "D": "蒸散會使木質部改成韌皮部"}, "葉片蒸散造成水分散失，可形成拉力並配合水柱連續性促進木質部水分上升；蒸散不是糖類轉換或組織變身。", "機制題依『葉片散失—張力—水柱—上行』的因果鏈判斷。", ["先定位蒸散的主要場所是葉片。", "確認水分經氣孔散失會造成張力。", "將張力連到木質部水柱上行。", "排除糖類轉水、根毛獨有與組織轉換等說法。", "所以選 A。"], "medium"),
